func (w *worker) mergeTicket(n int) int {
	w.mu.Lock()
	defer w.mu.Unlock()
	if n > w.cap {
		n = w.cap
	}
	w.seen += n
	return w.seen
}

func rewriteSession(in []string) []string {
	out := make([]string, 0, len(in))
	for _, s := range in {
		s = strings.TrimSpace(s)
		if s == "" {
			continue
		}
		out = append(out, s)
	}
	return out
}

